-- CNE-MOD-CARGO-TRANSMISION: inserción idempotente, cotejada con DOF/SIDOF; conserva el acuerdo original.
BEGIN;
SET LOCAL lock_timeout='10s';
SET LOCAL statement_timeout='60s';
DO $ingest$
DECLARE p jsonb := $payload${"ley":{"id":"cd03a15e-0f2c-53e7-b07f-207b3c9f3c12","titulo":"Acuerdo de la Comisión Nacional de Energía por el que se modifica el diverso por el que se emite la metodología para la determinación del cargo correspondiente al servicio de transmisión de energía eléctrica que preste la Suministradora a las Personas Permisionarias con centrales de generación de energía eléctrica, que cuenten con contrato de interconexión y convenio para el servicio de transmisión de energía eléctrica celebrados al amparo de la Ley del Servicio Público de Energía Eléctrica, publicado el 18 de junio de 2026","siglas":"CNE-MOD-CARGO-TRANSMISION","fecha_publicacion":"2026-09-30","fecha_ultima_reforma":null,"vigente":null,"temas_clave":["Metodología de transmisión","Permisionarios legados","Migración voluntaria al marco de la LSE"],"url_original":"https://sidof.segob.gob.mx/notas/docFuente/5799964","tipo":"acuerdo"},"articulos":[{"id":"14c159c7-5271-548a-ae67-ba6d46e3d167","ley_id":"cd03a15e-0f2c-53e7-b07f-207b3c9f3c12","orden":0,"identificador":"Nota editorial · modificación relacionada","contenido":"### Nota editorial · modificación relacionada\n\nEste acuerdo del 30 de septiembre de 2026 modifica únicamente los transitorios Tercero y Cuarto del instrumento original publicado el 18 de junio de 2026. Se incorpora por separado; no sustituye ni consolida el acuerdo original.\n\nInstrumento original: <a href=\"/#ley-6be7cf44-0134-5950-b9d0-a898d4ec5ced\" target=\"_blank\" rel=\"noopener noreferrer\">Acuerdo de la Comisión Nacional de Energía por el que se emite la metodología para la determinación del cargo correspondiente al servicio de transmisión de energía eléctrica que preste la Suministradora a las Personas Permisionarias con centrales de generación de energía eléctrica, que cuenten con contrato de interconexión y convenio para el servicio de transmisión de energía eléctrica celebrados al amparo de la Ley del Servicio Público de Energía Eléctrica</a> · [fuente oficial](https://sidof.segob.gob.mx/notas/docFuente/5790939).\n\nModificación publicada en el DOF: [https://sidof.segob.gob.mx/notas/docFuente/5799964](https://sidof.segob.gob.mx/notas/docFuente/5799964) · edición matutina PDF: [https://sidof.segob.gob.mx/notas/getNewsletter/30-09-2026/Matutina/329925](https://sidof.segob.gob.mx/notas/getNewsletter/30-09-2026/Matutina/329925).\n\nLa publicación conserva por separado el Artículo Único modificatorio, los textos reformados de los transitorios Tercero y Cuarto, el transitorio de entrada en vigor y la firma. No se certifica vigencia ni se presenta un texto consolidado. Fuente revisada el 1 de octubre de 2026.\n","tipo_articulo":"complementario","titulo_nombre":"Información editorial","capitulo_nombre":null,"seccion_nombre":null},{"id":"be3a843e-3014-5b0c-a01b-2842d7284efc","ley_id":"cd03a15e-0f2c-53e7-b07f-207b3c9f3c12","orden":1,"identificador":"Preámbulo del acuerdo","contenido":"<div>Acuerdo de la Comisión Nacional de Energía por el que se modifica el diverso por el que se emite la metodología para la determinación del cargo correspondiente al servicio de transmisión de energía eléctrica que preste la Suministradora a las Personas Permisionarias con centrales de generación de energía eléctrica, que cuenten con contrato de interconexión y convenio para el servicio de transmisión de energía eléctrica celebrados al amparo de la Ley del Servicio Público de Energía Eléctrica, publicado el 18 de junio de 2026.</div>\n<div>Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Comisión Nacional de Energía.</div>\n<div>JUAN CARLOS SOLÍS ÁVILA, Director General de la Comisión Nacional de Energía, con fundamento en los artículos 25, párrafo quinto, 27, párrafo sexto, 28, párrafo noveno, y 90, párrafo primero, de la Constitución Política de los Estados Unidos Mexicanos; 1, 2, fracción I, 17, 26, fracción IX, y 33, último párrafo, de la Ley Orgánica de la Administración Pública Federal; 1, 2, párrafo primero, 7, fracciones I, II y III, 8, fracciones I, VII y IX, 12, 14, párrafo primero, 16, fracciones VI, X, XIX, XXIII y XXV, y 17, fracciones I, II, III y XIV, de la Ley de la Comisión Nacional de Energía; 1, 2, 6 y 7 de la Ley del Sector Eléctrico; 2, párrafo primero, apartado F, fracción III, 71, 77 y 78 del Reglamento Interior de la Secretaría de Energía; 2, 7, 13 y 19 del Reglamento Interior de la Comisión Nacional de Energía; 7, fracción II del Acuerdo número CT/1.SE/2-2025, por el que se aprobaron las Reglas de Operación del Comité Técnico de la Comisión Nacional de Energía, así como el Acuerdo número CT/8.SE/4-2026 expedido por el Comité Técnico de la Comisión Nacional de Energía y,</div>\n<div>Que el artículo 25, párrafo quinto de la Constitución Política de los Estados Unidos Mexicanos (Constitución) prevé que el sector público tiene a su cargo, de manera exclusiva, las áreas estratégicas que se señalan en el artículo 28, párrafo cuarto de la Constitución y que, tratándose de la planeación y el control del Sistema Eléctrico Nacional (SEN) y del servicio público de transmisión y distribución de energía eléctrica, la Nación debe llevar a cabo dichas actividades en términos de lo dispuesto en el artículo 27, párrafo sexto de la Constitución.</div>\n<div>Que de conformidad con el artículo 27, párrafo sexto de la Constitución corresponde exclusivamente a la Nación la planeación y el control del SEN en los términos del artículo 28 constitucional, señalando que las leyes deben determinar la forma en que los particulares pueden participar en las demás actividades de la industria eléctrica.</div>\n<div>Que el artículo 28, párrafo noveno de la Constitución establece que el Poder Ejecutivo Federal, por conducto de la dependencia encargada de conducir y supervisar la política energética del país, cuenta con las atribuciones para llevar a cabo la regulación técnica y económica, así como la facultad sancionadora en materia energética en los términos que determine la ley.</div>\n<div>Que el 18 de marzo de 2025 se publicó en el Diario Oficial de la Federación (DOF) el Decreto por el que se expiden, entre otras, la Ley del Sector Eléctrico y la Ley de la Comisión Nacional de Energía (LCNE), mediante las cuales se estableció el nuevo marco jurídico aplicable al sector eléctrico y se determinaron las atribuciones de la Comisión Nacional de Energía (CNE) en materia de regulación, supervisión y determinación de metodologías y tarifas del sector energético.</div>\n<div>Que de conformidad con los artículos 1, 2, fracción I, 17, 26, fracción IX y 33, último párrafo de la Ley Orgánica de la Administración Pública Federal; 2, párrafo primero de la LCNE; 2, apartado F, fracción III y 71 del Reglamento Interior de la Secretaría de Energía y 2 del Reglamento Interior de la Comisión Nacional de Energía, la CNE es un órgano administrativo desconcentrado, de carácter técnico, sectorizado a la Secretaría de Energía, que cuenta con independencia técnica, operativa, de gestión y de decisión, que tiene por objeto regular, supervisar e imponer sanciones en las actividades del sector energético de conformidad con las disposiciones aplicables en materia de planeación vinculante en el ámbito de su competencia.</div>\n<div>Que de conformidad con el artículo 3 de la LCNE, la CNE, en el ejercicio de sus funciones, se rige por los principios de eficacia, eficiencia, honestidad, imparcialidad, integridad, objetividad, productividad, profesionalización, transparencia, participación social, austeridad y rendición de cuentas, con el fin de contribuir a garantizar la soberanía, seguridad, autosuficiencia y justicia energéticas de la Nación acorde con la política energética que establezca la Secretaría de Energía.</div>\n<div>Que los artículos 7, fracciones I, II y III, y 8, fracciones I y VII de la LCNE establecen que la CNE tiene atribuciones para emitir resoluciones, acuerdos, criterios de interpretación, directivas, bases y demás actos administrativos necesarios para el cumplimiento de sus atribuciones, vigilar y supervisar su cumplimiento; emitir la metodología para determinar las tarifas y contraprestaciones del sector eléctrico y realizar el seguimiento de costos; así como promover el desarrollo ordenado, continuo y seguro de las actividades de generación de electricidad, los servicios públicos de transmisión y distribución eléctrica, y la comercialización de electricidad.</div>\n<div>Que el artículo Cuarto Transitorio de la Ley del Sector Eléctrico dispone que la CNE debe revisar y actualizar las metodologías de transmisión y las metodologías de las tarifas reguladas del Servicio Público de Transmisión, para dar cumplimiento a lo establecido en la reforma constitucional en materia de áreas y empresas estratégicas, publicada en el DOF el 31 de octubre de 2024. Lo anterior, para garantizar la Eficiencia, Calidad, Confiabilidad, Continuidad, Seguridad y Sostenibilidad del SEN.</div>\n<div>Que en cumplimiento de lo establecido en el artículo referido en el considerando inmediato anterior, el 18 de junio de 2026 se publicó en el DOF el Acuerdo de la Comisión Nacional de Energía por el que se emite la metodología para la determinación del cargo correspondiente al servicio de transmisión de energía eléctrica que preste la Suministradora a las Personas Permisionarias con centrales de generación de energía eléctrica, que cuenten con contrato de interconexión y convenio para el servicio de transmisión de energía eléctrica celebrados al amparo de la Ley del Servicio Público de Energía Eléctrica (Acuerdo de la Metodología de Transmisión).</div>\n<div>Que en esa misma fecha, la Secretaría de Energía publicó el Acuerdo por el que se emiten los Lineamientos para la migración voluntaria y expedita de autoabastecimiento y cogeneración de energía eléctrica a las figuras previstas en la Ley del Sector Eléctrico, el cual prevé en el párrafo segundo del artículo Segundo Transitorio que la Comisión Nacional de Energía, el Centro Nacional de Control de Energía, la Comisión Federal de Electricidad y CFE Intermediación de Contratos Legados, S.A. de C.V., pueden establecer mecanismos, como parte de las estrategias o programas que comprenden la simplificación administrativa y agilidad técnica, para promover la participación de las personas titulares de los permisos otorgados al amparo de la Ley del Servicio Público de Energía Eléctrica para solicitar el procedimiento de migración voluntaria y expedita establecido en los lineamientos que se emiten a través del Acuerdo referido, de conformidad con lo previsto en el artículo Sexto Transitorio de la Ley del Sector Eléctrico.</div>\n<div>Que los citados Lineamientos fueron modificados mediante Acuerdo publicado en el DOF el 8 de septiembre de 2026. Derivado de lo anterior, resulta necesario modificar los artículos Tercero y Cuarto Transitorios del Acuerdo de la Metodología de Transmisión, a efecto de brindar certeza jurídica sobre el periodo en que aplica la excepción prevista en el artículo Tercero Transitorio del citado Acuerdo a las Personas Permisionarias con centrales de generación de energía eléctrica que cuenten con contrato de interconexión y convenio para el Servicio de Transmisión de energía eléctrica celebrados al amparo de la Ley del Servicio Público de Energía Eléctrica, y que se encuentren en los supuestos establecidos en este.</div>\n<div>Que de igual forma, resulta necesario prever expresamente que las Personas Permisionarias puedan renunciar a la excepción prevista en el artículo Transitorio Tercero del Acuerdo de la Metodología de Transmisión.</div>\n<div>Que mediante la Octava Sesión Extraordinaria del 23 de septiembre de 2026, el Comité Técnico de la CNE aprobó el Acuerdo número CT/8.SE/4-2026, por el que se autoriza la emisión del presente Acuerdo.</div>\n<div>Que en el ejercicio de las facultades de la CNE y en apego a las consideraciones anteriores resulta necesario modificar el Acuerdo de la Metodología de Transmisión en relación con su aplicabilidad, por lo que, tengo a bien emitir el siguiente:</div>\n<div>ACUERDO DE LA COMISIÓN NACIONAL DE ENERGÍA POR EL QUE SE MODIFICA EL DIVERSO POR EL QUE SE EMITE LA METODOLOGÍA PARA LA DETERMINACIÓN DEL CARGO CORRESPONDIENTE AL SERVICIO DE TRANSMISIÓN DE ENERGÍA ELÉCTRICA QUE PRESTE LA SUMINISTRADORA A LAS PERSONAS PERMISIONARIAS CON CENTRALES DE GENERACIÓN DE ENERGÍA ELÉCTRICA, QUE CUENTEN CON CONTRATO DE INTERCONEXIÓN Y CONVENIO PARA EL SERVICIO DE TRANSMISIÓN DE ENERGÍA ELÉCTRICA CELEBRADOS AL AMPARO DE LA LEY DEL SERVICIO PÚBLICO DE ENERGÍA ELÉCTRICA, PUBLICADO EL 18 DE JUNIO DE 2026 EN EL DIARIO OFICIAL DE LA FEDERACIÓN</div>","tipo_articulo":"preambulo","titulo_nombre":"Modificación a la metodología de cargos de transmisión para permisionarios legados","capitulo_nombre":"Preámbulo","seccion_nombre":null},{"id":"cae6302d-2bea-51ee-87a6-8da400cf95c9","ley_id":"cd03a15e-0f2c-53e7-b07f-207b3c9f3c12","orden":2,"identificador":"Artículo Único · modificación de transitorios","contenido":"<div>Artículo Único. Se modifican los artículos Tercero y Cuarto Transitorios del Acuerdo de la Comisión Nacional de Energía por el que se emite la metodología para la determinación del cargo correspondiente al servicio de transmisión de energía eléctrica que preste la Suministradora a las Personas Permisionarias con centrales de generación de energía eléctrica, que cuenten con contrato de interconexión y convenio para el servicio de transmisión de energía eléctrica celebrados al amparo de la Ley del Servicio Público de Energía Eléctrica, para quedar en los siguientes términos:</div>","tipo_articulo":"ordinario","titulo_nombre":"Modificación a la metodología de cargos de transmisión para permisionarios legados","capitulo_nombre":"Cuerpo del instrumento","seccion_nombre":null},{"id":"cb074064-0ffd-5be8-b579-d5b642d1a467","ley_id":"cd03a15e-0f2c-53e7-b07f-207b3c9f3c12","orden":3,"identificador":"Transitorio Tercero · texto modificado","contenido":"<div>\"TERCERO. En el marco del procedimiento de migración voluntaria y expedita al que hace referencia el artículo Sexto Transitorio de la Ley del Sector Eléctrico, y de conformidad con los lineamientos de referencia que para tal efecto emita la Secretaría de Energía, no les es aplicable la Metodología de Transmisión establecida en el presente Acuerdo, durante el plazo comprendido entre el 19 de octubre de 2026 y el 6 de octubre de 2028 a las Personas Permisionarias con centrales de generación de energía eléctrica que cumplan con las siguientes condiciones:</div>\n<div>I. Que cuenten con un contrato de interconexión y Convenio de Transmisión vigentes, celebrados al amparo de la Ley del Servicio Público de Energía Eléctrica, y</div>\n<div>II. Que inicien el procedimiento de migración voluntaria y expedita a las figuras de la Ley del Sector Eléctrico, mediante el registro de la manifestación de interés para participar en dicho procedimiento y presenten la solicitud de migración correspondiente, en términos de los lineamientos a que se refiere el artículo Sexto Transitorio de la Ley del Sector Eléctrico, que para tal efecto emita la Secretaría de Energía.</div>\n<div>La excepción de la aplicación de la Metodología de Transmisión a que se refiere este artículo transitorio surte efectos a partir del día siguiente a aquel en que se cumplan las condiciones previstas en las fracciones I y II del presente artículo, sin que pueda iniciar antes del 19 de octubre de 2026 ni tener efectos retroactivos.</div>\n<div>Durante dicho plazo de excepción, las Personas Permisionarias deben continuar operando conforme a lo estipulado en el contrato de interconexión y el Convenio de Transmisión que tengan vigentes a la fecha de entrada en vigor del presente Acuerdo, y realizar el pago del cargo correspondiente al Servicio de Transmisión conforme a dichos instrumentos y la metodología de transmisión aplicable con anterioridad a la entrada en vigor del presente Acuerdo.</div>\n<div>La excepción de la aplicación de la Metodología de Transmisión referida en este transitorio se mantiene únicamente mientras se cumplan las condiciones previstas en el presente artículo y concluye el 6 de octubre de 2028, salvo lo previsto en el artículo Cuarto Transitorio del presente Acuerdo.</div>","tipo_articulo":"transitorio","titulo_nombre":"Modificación a la metodología de cargos de transmisión para permisionarios legados","capitulo_nombre":"Modificaciones al Acuerdo de la Metodología de Transmisión","seccion_nombre":null},{"id":"e3b4acd1-4fa5-5a8d-8578-e1d708d8bae1","ley_id":"cd03a15e-0f2c-53e7-b07f-207b3c9f3c12","orden":4,"identificador":"Transitorio Cuarto · texto modificado","contenido":"<div>CUARTO. Lo establecido en el artículo Transitorio anterior, queda sin efectos cuando las Personas Permisionarias referidas en dicha disposición actualicen alguno de los supuestos siguientes:</div>\n<div>I. No concluyan el procedimiento de migración voluntaria y expedita a las figuras de la Ley del Sector Eléctrico, establecido en los lineamientos a que se refiere el artículo Sexto Transitorio de la Ley del Sector Eléctrico, que para tal efecto emita la Secretaría de Energía;</div>\n<div>II. Se lleve a cabo la modificación del estatus del registro de activos físicos a habilitado e inicie operación en el Mercado Eléctrico Mayorista, de acuerdo con lo establecido en el procedimiento de migración voluntaria y expedita que se señala en la fracción anterior y conforme a las disposiciones jurídicas aplicables;</div>\n<div>III. Concluya la vigencia del contrato de interconexión y el Convenio de Transmisión celebrados en términos de la Ley del Servicio Público de Energía Eléctrica, o</div>\n<div>IV. Renuncien voluntariamente ante la Comisión Nacional de Energía, en cualquier momento, a la excepción prevista en el artículo Tercero Transitorio de este Acuerdo.</div>\n<div>En cualquiera de los supuestos mencionados en las fracciones anteriores, una vez que la Comisión Nacional de Energía notifique a las Personas Permisionarias los actos respectivos, de acuerdo con lo establecido en las disposiciones jurídicas aplicables, estas deben realizar el pago de los cargos por el Servicio de Transmisión conforme al presente Acuerdo, o bien, de las tarifas que correspondan en el Mercado Eléctrico Mayorista, a partir del siguiente periodo de facturación respectivo inmediato posterior a la fecha de la referida notificación.\"</div>","tipo_articulo":"transitorio","titulo_nombre":"Modificación a la metodología de cargos de transmisión para permisionarios legados","capitulo_nombre":"Modificaciones al Acuerdo de la Metodología de Transmisión","seccion_nombre":null},{"id":"c6abca30-8adf-50e9-a5b7-84b81d6e3125","ley_id":"cd03a15e-0f2c-53e7-b07f-207b3c9f3c12","orden":5,"identificador":"Transitorios · ÚNICO · entrada en vigor","contenido":"<div>TRANSITORIOS</div>\n<div>ÚNICO. El presente Acuerdo entra en vigor el día de su publicación en el Diario Oficial de la Federación.</div>","tipo_articulo":"transitorio","titulo_nombre":"Modificación a la metodología de cargos de transmisión para permisionarios legados","capitulo_nombre":"Entrada en vigor","seccion_nombre":null},{"id":"4e93a2cb-7b2a-5c92-9267-cf07ea3cb120","ley_id":"cd03a15e-0f2c-53e7-b07f-207b3c9f3c12","orden":6,"identificador":"Firma del acuerdo","contenido":"<div>Ciudad de México, a 23 de septiembre de 2026.- El Director General, Juan Carlos Solís Ávila.- Rúbrica.</div>","tipo_articulo":"complementario","titulo_nombre":"Modificación a la metodología de cargos de transmisión para permisionarios legados","capitulo_nombre":"Firma","seccion_nombre":null}],"temas":[{"nivel":"titulo","nombre":"Información editorial","orden":0},{"nivel":"capitulo","nombre":"Preámbulo","orden":1},{"nivel":"capitulo","nombre":"Cuerpo del instrumento","orden":2},{"nivel":"capitulo","nombre":"Modificaciones al Acuerdo de la Metodología de Transmisión","orden":3},{"nivel":"capitulo","nombre":"Entrada en vigor","orden":4},{"nivel":"capitulo","nombre":"Firma","orden":5}],"fuente":{"url_html":"https://sidof.segob.gob.mx/notas/docFuente/5799964","url_pdf":"https://sidof.segob.gob.mx/notas/getNewsletter/30-09-2026/Matutina/329925","sha256_pdf":"598b6f92b41292cebf27dc3f0dce793b7d6a02477e56a3f0ca49866ce528334c","page_count":344,"pdf_pages_printed":[46,47,48]}}$payload$::jsonb; lid uuid;
BEGIN
 lid := (p->'ley'->>'id')::uuid;
 LOCK TABLE public.leyes,public.articulos,public.temas IN SHARE ROW EXCLUSIVE MODE;
 IF EXISTS(SELECT 1 FROM public.leyes WHERE id=lid OR lower(siglas)=lower(p->'ley'->>'siglas') OR lower(titulo)=lower(p->'ley'->>'titulo') OR url_original=p->'ley'->>'url_original') THEN RAISE EXCEPTION 'El instrumento ya existe: revisar, no reemplazar'; END IF;
 INSERT INTO public.leyes(id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo) SELECT id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo FROM jsonb_populate_record(null::public.leyes,p->'ley');
 INSERT INTO public.articulos(id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden) SELECT id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden FROM jsonb_populate_recordset(null::public.articulos,p->'articulos');
 INSERT INTO public.temas(ley_id,nivel,nombre,orden) SELECT lid,t->>'nivel',t->>'nombre',(t->>'orden')::int FROM jsonb_array_elements(p->'temas')t;
 IF (SELECT count(*) FROM public.articulos WHERE ley_id=lid)<>jsonb_array_length(p->'articulos') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'articulos')b LEFT JOIN public.articulos a ON a.id=(b->>'id')::uuid WHERE a.id IS NULL OR (to_jsonb(a)-'fts'-'created_at') IS DISTINCT FROM b) THEN RAISE EXCEPTION 'Fallo de cotejo exacto de artículos'; END IF;
 IF (SELECT count(*) FROM public.temas WHERE ley_id=lid)<>jsonb_array_length(p->'temas') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'temas')b WHERE NOT EXISTS(SELECT 1 FROM public.temas t WHERE ley_id=lid AND (to_jsonb(t)-'id'-'ley_id'-'created_at')=b)) THEN RAISE EXCEPTION 'Fallo de cotejo de estructura'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.leyes l WHERE id=lid AND to_jsonb(l)-'created_at'=p->'ley') THEN RAISE EXCEPTION 'Metadatos diferentes'; END IF;
 IF EXISTS(SELECT 1 FROM public.articulos WHERE ley_id=lid AND (nullif(trim(contenido),'') IS NULL OR fts IS NULL OR fts=''::tsvector)) THEN RAISE EXCEPTION 'Texto o índice FTS vacío'; END IF;
END $ingest$;
COMMIT;
SELECT l.siglas,l.id,(SELECT count(*) FROM public.articulos a WHERE a.ley_id=l.id) fragmentos,(SELECT count(*) FROM public.temas t WHERE t.ley_id=l.id) temas FROM public.leyes l WHERE l.id='cd03a15e-0f2c-53e7-b07f-207b3c9f3c12';
